#!/usr/bin/env sage
"""Compare the corrected quotient residual with the W terminal packet.

This is an exact finite experiment.  It asks whether the real
moment-raised source left by the order-66 quotient operator is already
a short constant-coefficient convolution of the origin-cancelled W
coordinate at fixed M.
"""


# This file was *autogenerated* from the file problems/3.2/research/scripts/q32_log_source_w_probe.sage
from sage.all_cmdline import *   # import sage library

_sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_6 = Integer(6); _sage_const_2 = Integer(2); _sage_const_4 = Integer(4); _sage_const_7 = Integer(7); _sage_const_3 = Integer(3); _sage_const_67 = Integer(67); _sage_const_80 = Integer(80); _sage_const_90 = Integer(90); _sage_const_10 = Integer(10); _sage_const_66 = Integer(66); _sage_const_11 = Integer(11); _sage_const_5 = Integer(5)
from fractions import Fraction
from math import comb
from pathlib import Path
import sys

HERE = Path(__file__).resolve().parent
sys.path.insert(_sage_const_0 , str(HERE))

# Provides integer_coefficients, multiplier, and origin_operator.
load(str(HERE / "q32_doubled_period_gauge_audit.sage"))
from q32_cartier_packet_audit import coefficient, polytope_points


def convolution(left, right):
    out = [QQ.zero()] * (len(left) + len(right) - _sage_const_1 )
    for i, aa in enumerate(left):
        for j, bb in enumerate(right):
            out[i + j] += aa * bb
    return out


quadratics = (
    (_sage_const_1 , -_sage_const_6 , _sage_const_1 ),
    (-_sage_const_1 , _sage_const_2 , _sage_const_1 ),
    (_sage_const_2 , -_sage_const_4 , _sage_const_1 ),
    (QQ(-_sage_const_1 ) / _sage_const_2 , _sage_const_0 , _sage_const_1 ),
    (QQ(_sage_const_7 ) / _sage_const_4 , -_sage_const_3 , _sage_const_1 ),
    (_sage_const_1 , _sage_const_2 , _sage_const_1 ),
    (-_sage_const_1 , -_sage_const_2 , _sage_const_1 ),
    (QQ(_sage_const_1 ) / _sage_const_2 , -_sage_const_2 , _sage_const_1 ),
    (QQ(_sage_const_1 ) / _sage_const_4 , -_sage_const_1 , _sage_const_1 ),
    (-_sage_const_2 , _sage_const_0 , _sage_const_1 ),
    (QQ(-_sage_const_1 ) / _sage_const_4 , -_sage_const_1 , _sage_const_1 ),
)
q = [QQ.one()]
for factor in quadratics:
    q = convolution(q, [QQ(entry) for entry in factor])
stable_operator = convolution(convolution(q, q), q)
assert len(stable_operator) == _sage_const_67 


def fixed_first_cell_shell(moment, endpoint):
    return ZZ(
        sum(
            coefficient(
                moment,
                endpoint * point[_sage_const_0 ],
                endpoint * point[_sage_const_1 ],
                endpoint * point[_sage_const_2 ],
            )
            for point in polytope_points(_sage_const_1 )
        )
    )


def packet_values(moment, endpoint, maximum_order):
    raw = [
        fixed_first_cell_shell(moment, endpoint - residue)
        for residue in range(maximum_order + _sage_const_1 )
    ]
    return [
        ZZ(
            sum(
                (-_sage_const_1 )**residue
                * binomial(order, residue)
                * raw[residue]
                for residue in range(order + _sage_const_1 )
            )
        )
        for order in range(maximum_order + _sage_const_1 )
    ]


def solve_and_test_convolution(residuals, source, order):
    rows = []
    rhs = []
    for start in range(order + _sage_const_1 ):
        rows.append(
            [source[start + shift] for shift in range(order + _sage_const_1 )]
        )
        rhs.append(residuals[start])
    matrix_value = matrix(QQ, rows)
    if matrix_value.rank() < order + _sage_const_1 :
        return None
    coefficients_value = matrix_value.solve_right(vector(QQ, rhs))
    good = all(
        residuals[start]
        == sum(
            coefficients_value[shift] * source[start + shift]
            for shift in range(order + _sage_const_1 )
        )
        for start in range(len(residuals))
    )
    return good, coefficients_value


for moment in (_sage_const_80 , _sage_const_90 ):
    global_index = moment + _sage_const_1 
    max_start = _sage_const_10 
    max_w_shift = _sage_const_6 
    maximum_order = _sage_const_66  + max_start + max_w_shift
    y_values = packet_values(moment, moment, maximum_order)

    shifted_pairs = []
    for shift in range(origin_operator.order() + _sage_const_1 ):
        shifted_moment = global_index + shift
        left = packet_values(
            shifted_moment, moment - _sage_const_1 , maximum_order
        )
        right = packet_values(
            shifted_moment, moment + _sage_const_1 , maximum_order
        )
        shifted_pairs.append(
            [left[index] + right[index]
             for index in range(maximum_order + _sage_const_1 )]
        )

    w_values = [
        sum(
            ZZ(integer_coefficients[shift](n=global_index))
            * shifted_pairs[shift][order]
            for shift in range(origin_operator.order() + _sage_const_1 )
        )
        - ZZ(multiplier(n=global_index)) * y_values[order]
        for order in range(maximum_order + _sage_const_1 )
    ]
    residuals = [
        sum(
            stable_operator[shift] * y_values[start + shift]
            for shift in range(_sage_const_67 )
        )
        for start in range(max_start + _sage_const_1 )
    ]
    print("MOMENT", moment)
    print("RESIDUAL_BITS",
          [abs(value.numerator()).nbits() for value in residuals])
    print("W_BITS", [abs(value).nbits() for value in w_values[:_sage_const_11 ]])
    print("SCALAR_RATIOS",
          [residuals[start] * w_values[_sage_const_0 ]
           == residuals[_sage_const_0 ] * w_values[start]
           for start in range(_sage_const_1 , _sage_const_5 )])
    for order in range(_sage_const_1 , max_w_shift + _sage_const_1 ):
        result = solve_and_test_convolution(
            residuals, w_values, order
        )
        print(
            "W_CONVOLUTION",
            order,
            None if result is None else result[_sage_const_0 ],
        )

